<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('Village_group/area_list')}">返回城市配置</a>					<a href="{pigcms{:U('Village_group/leader_area_level_list',array('city_id'=>$_GET['city_id']))}" class="on">佣金等级管理</a>					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Village_group/add_leader_area_level',array('city_id'=>$_GET['city_id']))}','添加一个佣金等级',650,500,true,false,false,addbtn,'add',true);" style="margin-left:20px;">添加等级</a>					<if condition="$config.open_recharge_level eq 1">					</if>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th width="50px">ID</th>								<th >等级名称</th>								<th >等级级别</th>								<th >佣金获取比率(%)</th>								<th >销售区间值</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($level_list)">								<volist name="level_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.lname}</td>                                        <td>{pigcms{$vo.level}</td>                                        <td>{pigcms{$vo.leader_money}</td>                                        <td>{pigcms{$vo.min_sale_num}-{pigcms{$vo.max_sale_num}</td>										<td><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Village_group/add_leader_area_level',array('lid'=>$vo['id'],'city_id'=>$_GET['city_id']))}','编辑等级信息',650,500,true,false,false,editbtn,'edit',true);">编 辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="lid={pigcms{$vo['id']}" url="/admin.php?g=System&c=Village_group&a=del_leader_area_level">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="7">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="7">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>